\u006a\u0032\u007e\u004b\u002c\u0057\u0035\u0056\u005f\u0029\u004b\u007b\u003e\u0031\u007d\u007b\u004f\u0029\u0053\u0071\u004d\u006c\u0053\u0037\u0071\u0044\u007c\u0053\u004b\u0073\u003b\u006e\u0055\u0042\u0060\u006e\u0032\u004f\u007e\u002d\u0057\u0066\u0023\u005c\u007b\u0036\u0077\u002d\u0025\u003e\u0046\u0072\u0066\u0028\u0064\u0026\u0064\u007c\u002f\u0077\u007b\u0047\u007d\u007a\u0027\u007c\u005e\u0052\u0043\u0035\u0073\u0020\u0033\u005a\u0047\u0054\u003e\u004d\u004d\u002b\u0050\u002e\u003b\u0024\u006d\u0026\u0047\u003e\u0071\u003d\u005b\u004f\u0037\u0025\u006c\u002a\u005a\u0061\u0031\u0040\u0074\u0027\u007d\u0034\u002c\u0046\u007b\u0064\u007e\u004a\u007d\u005e\u0050\u0027\u0045\u0061\u0071\u0029\u002b\u0048\u0048\u003c\u0039\u0073\u006f\u004e\u0028\u007c\u0024\u0033\u0039\u0072\u004f\u0053\u002a\u002c\u003c\u0027\u0052\u007c\u003c\u003a\u0066\u0056\u004e\u0034\u003f\u003e\u0079\u0053\u0038\u0057\u0059\u007e\u0035\u003a\u0057\u0054\u005d\u0059\u0055\u0031\u006c\u0079\u002c\u0077\u0072\u0044\u002d\u006f\u0070\u005b\u0068\u003b\u005e\u003a\u003a\u0062\u0060\u007d\u0061\u0020\u0048\u0047\u0036\u0072\u0045\u0024\u0037\u0056\u0060\u0039\u005a\u0043\u0056\u004c\u006a\u0055\u0034\u002e\u0073\u0064\u004d\u003d\u0048\u0023\u0045\u0044\u0035\u004b\u0028\u0056\u0047\u0073\u0071\u0078\u0026\u0064\u003c\u004c\u004a\u0054\u0021\u006b\u007b\u003d\u002d\u0026\u0058\u0072\u0022\u0079\u0051\u0052\u0071\u0051\u0027\u0035\u004c\u0035\u0021\u0065\u003d\u0036\u0034\u0058\u0034\u006b\u003e\u0072\u0034\u0021\u0031\u0070\u006d\u007b\u004c\u003f\u0070\u002d\u0054\u007b\u002a\u0056\u003a\u007c\u0029\u004a\u0035\u004e\u005f\u0044\u007d\u0038\u0022\u0030\u0058\u0057\u0053\u003d\u0072\u0030\u0055\u004a\u006e\u0049\u0020\u002b\u0069\u0056\u0057\u0025\u004f\u0070\u005f\u0076\u007c\u0023\u0069\u005f\u0073\u0039\u0030\u0046\u0044\u007e\u0029\u0036\u0024\u0049\u005c\u0036\u005b\u0079\u003c\u002e\u005d\u007c\u007d\u004d\u0028\u005f\u0039\u0048\u0038\u0076\u0051\u003b\u0068\u005f\u004a\u007a\u004c\u006d\u0060\u0022\u005c\u004d\u0031\u0078\u006e\u0074\u007c\u0024\u006f\u0061\u0023\u0048\u0035\u0056\u007b\u0033\u007a\u002d\u0065\u0024\u0024\u006f\u0060\u0032\u0027\u0025\u0049\u0068\u0063\u0031\u005e\u0035\u0028\u0038\u0069\u0053\u0023\u0063\u004c\u0039\u004c\u007b\u0048\u003b\u003c\u0034\u003c\u0033\u007c\u0060\u0048\u0075\u002e\u005c\u0036\u003e\u0021\u0052\u005c\u0044\u0051\u007a\u0050\u0070\u007a\u0033\u004e\u0025\u0044\u005b\u0047\u0075\u005f\u0060\u0078\u0025\u006b\u0069\u003f\u004e\u007d\u003a\u007a\u003d\u007e\u0078\u0037\u005d\u0068\u005f\u0066\u0051\u0029\u0058\u0074\u0040\u0044\u002d\u004c\u0039\u005b\u0066\u0074\u0033\u0071\u0029\u002a\u004f\u0062\u005d\u0042\u0052\u007b\u006c\u006f\u0020\u0056\u0035\u0037\u007b\u0066\u004e\u0047\u0056\u006e\u005d\u0072\u0056\u002b\u0076\u0060\u0069\u0030\u0022\u0064\u007d\u0033\u0063\u0070\u0059\u0031\u0069\u0070\u0074\u0059\u0028\u0071\u0037\u003c\u003d\u0034\u0058\u0035\u003d\u0077\u0033\u0063\u0053\u0043\u0051\u0034\u0044\u0054\u0035\u0032\u0025\u0026\u0043\u0053\u004e\u0050\u002c\u0068\u0062\u0029\u005f\u0075\u0060\u0033\u007e\u003c\u0036\u003f\u004d\u0061\u0048\u0033\u0047\u0040\u0046\u002f\u0022\u0027\u0044\u003a\u006c\u0022\u0059\u0067\u0067\u0030\u0030\u002b\u003b\u002b\u0042\u0054\u0058\u0028\u0040\u007e\u0047\u0061\u006b\u0044\u004d\u0033\u003b\u003c\u0046\u0020\u0038\u006a\u0078\u0054\u004f\u0054\u0021\u003e\u005c\u0067\u0056\u003c\u006b\u005d\u0038\u0059\u0032\u005a\u0033\u0059\u0065\u0034\u007e\u004a\u0068\u003c\u0036\u0079\u0067\u003e\u006f\u0076\u0052\u004e\u005e\u0070\u0073\u0043\u003b\u006c\u004a\u003f\u003d\u0076\u002e\u0032\u0024\u0020\u0059\u003c\u0020\u0052\u0059\u0025\u0061\u0039\u002a\u0058\u0021\u0069\u0065\u002f\u0025\u0042\u0046\u0043\u004b\u0037\u0078\u004a\u0034\u004a\u0040\u0041\u0078\u0053\u0076\u005c\u0072\u0026\u004b\u003c\u002b\u0053\u002b\u0059\u0047\u0027\u002d\u003d\u006b\u006c\u0058\u0071\u0045\u0044\u005c\u004d\u002a\u002c\u0056\u0076\u0055\u0049\u004c\u0023\u005e\u0055\u007b\u005c\u003e\u0058\u005f\u0048\u0043\u0050\u006f\u0057\u0071\u004d\u003e\u006a\u0047\u002a\u002f\u0078\u0048\u0021\u0023\u0042\u004b\u0068\u0066\u0047\u0031\u004d\u0023\u0028\u005d\u0073\u0049\u0033\u006d\u0079\u002e\u0036\u0076\u0064\u0034\u0068\u005f\u003b\u003e\u0057\u0078\u0072\u006f\u0076\u0049\u0061\u003d\u005a\u0037\u0050\u004e\u0043\u0028\u0076\u0041\u0057\u0052\u0052\u003d\u0029\u006f\u0035\u003c\u0027\u0063\u005f\u002d\u0024\u0042\u005e\u0076\u005b\u0036\u006c\u0052\u003b\u0046\u002f\u007a\u004e\u0059\u007b\u004b\u0050\u005b\u0073\u0053\u005c\u005a\u006c\u0070\u0039\u0056\u0043\u0022\u0076\u0023\u006d\u0054\u0078\u005d\u0070\u0053\u002a\u0074\u0034\u0057\u005b\u0066\u0079\u0077\u005b\u002b\u003c\u0053\u0077\u0077\u0052\u006f\u0036\u002c\u0068\u0077\u0032\u0049\u0050\u004c\u0075\u0055\u0070\u003c\u0034\u0042\u002f\u0051\u0069\u0051\u0025\u0027\u002a\u0058\u0078\u006f\u0069\u005b\u004d\u006a\u004d\u007a\u0064\u003e\u0059\u0071\u002c\u007c\u007d\u0047\u003f\u004b\u0040\u004d\u0031\u0027\u0033\u007a\u005e\u006f\u005f\u0028\u0053\u0023\u0034\u0077\u003d\u007e\u0060\u002d\u0070\u0059\u0027\u005d\u0051\u0059\u007a\u0050\u0035\u0073\u002c\u0025\u0070\u0067\u003d\u007e\u0061\u0077\u003d\u0028\u005c\u0031\u0020\u006a\u003e\u003b\u003c\u0064\u0042\u005f\u0055\u0064\u0042\u005a\u0058\u006b\u0029\u0054\u0055\u0036\u002c\u0074\u0044\u0040\u0063\u0034\u0032\u0033\u0047\u0033\u004d\u002a\u0062\u0075\u0052\u0037\u0023\u0029\u0044\u0028\u0048\u003c\u0069\u005b\u002d\u005e\u003b\u0067\u0025\u0071\u0032\u0054\u0027\u0039\u0032\u0048\u003a\u0049\u0077\u0047\u003a\u004f\u0044\u007c\u0052\u0053\u0034\u0029\u0053\u0073\u0058\u0033\u0023\u006e\u002e\u0069\u004b\u0025\u005b\u006b\u0054\u0064\u0047\u0054\u005c\u004f\u0052\u005e\u0070\u0037\u0076\u0075\u0050\u005d\u003f\u002b\u0044\u006d\u0072\u0069\u0064\u002b\u004b\u0068\u003e\u0032\u006a\u0020\u005c\u005c\u005f\u0055\u003e\u0067\u0074\u0076\u002a\u0031\u0037\u0065\u0076\u0038\u004f\u0036\u003f\u0029\u004d\u005d\u004f\u007c\u003d\u003c\u002d\u0024\u006c\u007d\u0067\u0058\u0051\u006d\u0037\u006d\u0036\u0022\u0038\u0041\u004b\u007c\u003a\u005b\u0058\u0077\u0036\u0070\u0052\u0033\u0045\u0045\u0061\u0044\u0055\u0070\u006e\u005a\u0025\u0032\u005b\u0039\u004e\u0078\u0068\u005b\u0024\u006d\u0068\u0078\u0046\u0037\u0032\u0048\u0069\u0021\u003d\u0040\u0051\u0075\u003d\u007e\u0035\u005e\u0078\u003d\u0063\u005a\u0071\u004c\u005e\u0031\u0047\u003b\u0023\u0022\u0070\u0050\u0021\u0061\u003e\u0078\u006e\u0049\u0041\u0079\u0027\u0038\u0057\u0064\u005e\u0037\u0077\u0067\u0063\u0036\u0063\u0067\u003b\u0065\u0065\u007b\u0020\u006e\u0061\u004f\u0030\u0035\u007b\u002c\u006c\u0022\u0074\u003c\u0034\u002c\u005a\u002e\u0058\u0033\u0060\u005b\u0033\u0028\u006f\u0040\u006e\u0027\u006a\u003c\u0030\u0075\u0045\u0031\u0040\u0042\u0021\u0066\u0037\u0076\u0039\u0050\u0066\u0045\u003f\u002e\u0047\u0079\u003a\u002a\u0073\u0072\u0061\u0048\u0073\u0030\u0047\u0063\u0069\u004e\u004c\u006b\u006d\u0021\u0029\u0051\u0028\u0036\u007b\u006a\u0040\u0024\u0054\u0063\u003a\u0024\u005b\u0033\u005f\u0063\u003d\u0038\u0068\u0057\u007a\u002a\u0043\u0049\u0071\u0035\u007c\u0049\u004d\u005e\u0079\u004e\u0024\u0069\u0061\u006e\u0033\u0024\u0041\u0053\u006a\u0054\u004b\u004b\u0062\u003f\u0055\u005b\u002c\u003f\u005a\u0036\u005b\u002c\u006c\u004f\u0032\u0058\u0041\u0060\u0048\u0057\u0041\u0036\u0045\u0064\u0062\u0048\u0031\u0060\u0056\u0025\u006f\u0073\u0039\u003f\u0040\u0032\u0051\u002a\u0074\u0040\u0067\u0045\u003d\u003e\u006e\u004d\u002b\u0045\u0049\u006b\u0035\u0064\u0069\u0046\u002c\u0046\u0061\u0037\u0032\u0070\u006b\u0054\u0036\u0058\u0043\u0034\u005a\u0057\u003b\u004c\u006c\u002b\u0072\u003a\u005b\u0025\u0062\u006f\u0052\u0026\u003a\u0035\u006c\u0065\u0040\u003e\u003d\u0069\u0065\u0056\u003c\u0042\u0052\u0066\u0071\u0045\u0042\u0070\u0064\u0038\u0073\u0027\u0063\u0041\u002e\u0042\u0029\u0057\u0043\u0027\u0071\u0059\u0030\u007d\u0066\u0054\u0039\u0024\u005e\u003a\u0042\u0027\u0042\u0075\u0027\u003d\u003b\u0078\u0039\u004a\u0046\u0026\u002a\u0059\u003f\u0066\u002b\u002c\u005d\u004c\u004d\u006f\u0066\u002e\u0064\u006b\u0064\u0061\u005a\u0041\u0040\u006f\u0076\u007a\u003a\u007e\u0035\u0026\u0071\u0068\u0038\u0039\u0073\u0067\u0032\u005d\u0056\u005b\u007a\u0026\u002f\u0070\u0025\u006f\u004d\u0034\u0053\u0020\u0025\u005d\u004f\u006b\u007a\u0076\u0062\u0049\u003e\u0067\u0039\u007a\u0063\u0036\u006c\u0038\u0038\u0078\u004d\u007a\u0069\u003e\u0031\u006a\u0023\u0029\u0071\u0040\u0040\u007a\u0064\u003a\u0042\u003c\u005b\u002b\u003c\u0067\u0031\u003e\u0025\u002c\u004b\u0042\u0036\u0079\u004e\u003c\u0055\u0077\u0070\u003d\u0027\u007c\u0065\u0064\u0049\u005c\u004b\u0065\u0066\u0044\u006c\u0059\u0027\u0046\u0072\u0062\u005e\u0061\u005d\u0073\u0032\u0049\u0034\u0069\u0070\u0067\u0047\u0056\u004f\u004c\u0026\u0021\u006b\u0020\u0044\u006e\u0072\u006c\u007b\u006b\u0059\u005c\u0063\u006e\u0057\u0042\u002b\u002f\u004f\u006f\u0073\u0068\u007b\u0068\u0022\u006b\u0026\u007e\u007e\u0056\u0034\u004d\u002d\u002d\u0059\u0047\u0025\u0044\u004c\u0040\u0036\u0036\u006d\u006a\u0023\u004e\u0050\u0032\u0048\u006e\u0049\u0062\u006a\u0028\u0068\u0036\u0049\u0031\u0038\u0064\u0035\u0053\u0032\u006c\u0050\u005e\u0072\u0032\u0030\u0062\u004b\u0062\u0064\u0038\u0021\u0058\u006a\u007c\u002d\u002c\u0069\u0036\u0064\u002b\u0070\u003e\u0041\u004a\u0044\u002c\u0026\u003e\u0049\u0024\u005b\u0022\u0051\u0062\u0034\u0069\u0022\u0051\u002e\u002c\u006d\u007b\u0024\u003a\u006c\u0022\u0067\u0064\u002e\u002c\u0051\u004d\u0056\u0076\u0061\u0020\u005e\u0076\u0053\u0049\u0032\u0074\u002f\u0073\u0066\u0045\u0022\u006f\u0052\u0020\u0025\u006b\u0065\u003d\u0033\u0072\u0038\u0030\u0076\u0061\u006b\u004c\u004e\u006d\u0051\u0052\u0054\u0028\u0073\u003e\u0027\u005c\u004e\u0074\u0078\u007c\u003b\u005a\u004c\u0026\u002a\u0057\u0039\u0053\u006a\u007a\u002c\u003e\u0048\u0020\u0028\u006d\u0049\u002e\u0065\u002b\u0064\u0077\u005f\u006d\u002c\u0065\u005a\u003d\u003f\u0029\u0033\u0048\u0040\u0059\u0020\u002d\u0076\u004f\u003a\u0027\u002b\u003e\u0048\u003d\u003d\u0041\u0059\u006f\u006e\u004b\u0072\u0072\u0033\u0025\u0048\u0023\u0057\u0065\u0020\u0079\u007a\u0026\u0075\u0054\u0022\u0058\u0062\u0037\u0039\u004b\u0046\u006e\u002c\u005f\u004a\u0078\u004d\u002b\u0057\u004f\u0059\u0068\u0043\u0073\u0066\u0046\u0032\u0024\u006b\u0054\u0022\u0073\u0025\u003f\u0052\u0032\u0026\u004b\u003e\u003a\u0025\u003a\u0071\u005b\u0033\u006a\u006c\u0056\u0032\u007c\u0035\u0056\u0030\u002e\u0066\u0025\u0026\u003e\u005f\u005c\u007e\u0023\u002b\u007a\u0064\u0043\u0051\u0028\u0063\u0036\u0048\u0052\u0058\u0063\u003e\u002d\u0039\u002d\u005f\u0038\u0077\u0022\u003e\u0058\u0052\u0063\u003c\u0023\u005c\u0066\u0036\u007c\u0070\u0027\u002f\u0049\u0054\u0068\u0070\u005a\u002f\u0063\u006a\u007c\u0024\u002e\u004e\u0055\u004b\u006e\u002e\u003a\u006c\u004d\u007d\u0042\u004d\u0024\u0062\u0052\u0030\u0064\u0062\u0063\u005b\u0028\u0025\u0060\u0064\u0049\u0062\u0060\u0069\u006b\u002f\u004e\u0031\u0046\u0070\u002d\u003c\u0043\u0051\u004c\u0041\u0049\u0056\u005d\u006a\u0058\u0063\u0044\u0043\u005c\u0056\u004f\u0079\u007a\u0071\u0025\u0054\u0057\u0038\u0071\u0042\u002f\u0021\u0063\u0072\u004d\u0071\u006a\u0074\u0044\u0067\u0060\u0055\u0047\u006d\u0065\u0053\u0072\u004f\u005c\u0069\u0039\u0023\u002d\u0074\u0076\u0065\u0061\u003b\u0058\u005a\u0065\u0065\u0035\u0028\u0036\u003d\u0059\u005d\u007a\u0032\u0062\u0068\u004a\u0023\u0077\u0060\u002f\u0058\u006c\u002f\u005e\u0043\u0069\u007a\u0072\u0060\u0030\u0044\u007d\u0039\u004e\u0068\u0046\u0030\u003d\u005b\u0065\u0033\u0055\u0048\u0049\u0038\u0072\u006d\u0036\u0079\u004e\u0069\u0052\u0048\u002b\u0031\u0064\u0036\u0079\u0058\u0060\u0023\u002e\u0025\u0042\u0034\u0023\u002a\u0068\u0069\u006d\u0070\u002c\u0022\u007e\u0031\u006d\u0043\u004e\u004a\u0030\u002f\u005a\u0073\u005a\u004a\u0020\u0070\u0072\u0023\u0036\u0063\u005d\u0072\u002d\u002c\u0033\u0046\u0027\u0076\u006e\u0035\u006c\u0063\u004e\u0047\u004b\u0060\u006e\u0040\u0070\u0042\u0021\u0059\u0057\u0030\u007e\u0026\u0021\u0071\u007b\u0035\u002a\u0027\u002f\u005a\u006f\u007c\u0060